export const ASSETS = {"/index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <meta name=\"theme-color\" content=\"#0d0b14\">\n  <title>animee space</title>\n  <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n\n  <link rel=\"stylesheet\" href=\"/css/style.css\">\n  <script src=\"https://cdn.jsdelivr.net/npm/hls.js@1/dist/hls.min.js\" defer></script>\n  <script type=\"module\" src=\"/js/app.js\"></script>\n</head>\n<body>\n  <header class=\"nav\">\n    <div class=\"nav-inner\">\n      <a class=\"logo\" href=\"#/\">animee<span> space</span></a>\n      <nav class=\"nav-links\" id=\"nav-links\">\n        <a href=\"#/\" data-nav=\"home\">Home</a>\n        <a href=\"#/search\" data-nav=\"search\">Browse</a>\n        <a href=\"#/watchlist\" data-nav=\"watchlist\">Watchlist</a>\n        <a href=\"#/account\" data-nav=\"account\" id=\"nav-account\">Sign in</a>\n      </nav>\n      <form class=\"nav-search\" id=\"nav-search\" role=\"search\">\n        <input type=\"search\" name=\"q\" placeholder=\"Search anime…\" autocomplete=\"off\" aria-label=\"Search anime\">\n        <div class=\"suggest\" id=\"suggest\" hidden></div>\n      </form>\n      <button class=\"menu-btn\" id=\"menu-btn\" aria-label=\"Menu\">☰</button>\n    </div>\n  </header>\n\n  <main id=\"app\" class=\"container\"></main>\n\n  <footer class=\"footer\">\n    <div class=\"container\">\n      <a class=\"logo small\" href=\"#/\">animee<span> space</span></a>\n      <p>Anime catalog and episodes from Anikoto.</p>\n    </div>\n  </footer>\n</body>\n</html>\n","/css/style.css":":root {\n  --bg: #0d0b14;\n  --bg-2: #15121f;\n  --bg-3: #1e1a2b;\n  --line: #2a2539;\n  --text: #ece9f5;\n  --muted: #9a94ad;\n  --accent: #ff7eb6;\n  --accent-2: #a78bfa;\n  --good: #5eead4;\n  --radius: 12px;\n  --nav-h: 64px;\n  color-scheme: dark;\n}\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: var(--bg);\n  color: var(--text);\n  font: 15px/1.5 system-ui, -apple-system, \"Segoe UI\", Roboto, \"Noto Sans Arabic\", sans-serif;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\na { color: inherit; text-decoration: none; }\nimg { display: block; max-width: 100%; }\nbutton, input, select { font: inherit; color: inherit; }\n.container { width: 100%; max-width: 1400px; margin: 0 auto; padding: 0 20px; }\nmain.container { flex: 1; padding-bottom: 40px; }\n\n/* ---------- nav ---------- */\n.nav {\n  position: sticky; top: 0; z-index: 50;\n  background: rgba(13, 11, 20, .85);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--line);\n}\n.nav-inner { max-width: 1400px; margin: 0 auto; height: var(--nav-h); display: flex; align-items: center; gap: 24px; padding: 0 20px; }\n.logo { font-weight: 800; font-size: 24px; letter-spacing: -.5px; }\n.logo span { background: linear-gradient(90deg, var(--accent), var(--accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }\n.logo.small { font-size: 20px; }\n.nav-links { display: flex; gap: 4px; }\n.nav-links a { padding: 8px 12px; border-radius: 8px; color: var(--muted); font-weight: 500; }\n.nav-links a:hover { color: var(--text); background: var(--bg-3); }\n.nav-links a.active { color: var(--text); background: var(--bg-3); }\n.nav-search { margin-left: auto; position: relative; width: min(360px, 40vw); }\n.nav-search input { width: 100%; background: var(--bg-3); border: 1px solid var(--line); border-radius: 999px; padding: 9px 16px; outline: none; }\n.nav-search input:focus { border-color: var(--accent-2); }\n.suggest { position: absolute; top: calc(100% + 6px); left: 0; right: 0; background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; box-shadow: 0 12px 40px #0008; }\n.suggest a { display: flex; gap: 10px; padding: 8px 10px; align-items: center; }\n.suggest a:hover, .suggest a.sel { background: var(--bg-3); }\n.suggest img { width: 38px; height: 54px; object-fit: cover; border-radius: 6px; }\n.suggest .s-title { font-weight: 600; font-size: 14px; }\n.suggest .s-meta { color: var(--muted); font-size: 12px; }\n.suggest .s-all { justify-content: center; color: var(--accent); font-weight: 600; }\n.menu-btn { display: none; background: none; border: 0; font-size: 22px; cursor: pointer; }\n\n.dev-banner { background: linear-gradient(90deg, #3b1d4a, #1d2a4a); color: #f5d0fe; text-align: center; font-size: 13px; padding: 6px 12px; }\n\n/* ---------- common ---------- */\n.btn { display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: var(--bg-3); padding: 10px 18px; border-radius: 999px; cursor: pointer; font-weight: 600; white-space: nowrap; }\n.btn:hover { border-color: var(--muted); }\n.btn.primary { background: linear-gradient(90deg, var(--accent), var(--accent-2)); color: #160d1c; border: 0; }\n.btn.primary:hover { filter: brightness(1.08); }\n.btn.sm { padding: 6px 12px; font-size: 13px; }\nselect, .input { background: var(--bg-3); border: 1px solid var(--line); border-radius: 10px; padding: 9px 12px; outline: none; }\nselect:focus, .input:focus { border-color: var(--accent-2); }\n\n.section { margin-top: 36px; }\n.section-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 14px; }\n.section-head h2 { margin: 0; font-size: 20px; }\n.section-head h2::before { content: \"\"; display: inline-block; width: 4px; height: 18px; background: var(--accent); border-radius: 2px; margin-right: 10px; vertical-align: -2px; }\n.section-head a { color: var(--accent); font-size: 14px; }\n\n.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 18px 14px; }\n.card { display: block; min-width: 0; }\n.poster { position: relative; aspect-ratio: 2 / 3; border-radius: var(--radius); overflow: hidden; background: var(--c, var(--bg-3)); }\n.poster img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s; }\n.card:hover .poster img { transform: scale(1.05); }\n.badge { position: absolute; font-size: 11px; font-weight: 700; padding: 3px 7px; border-radius: 6px; background: rgba(0,0,0,.72); }\n.badge.score { top: 8px; left: 8px; color: #fde68a; }\n.badge.eps { bottom: 8px; left: 8px; }\n.badge.airing { top: 8px; right: 8px; background: var(--good); color: #032; }\n.card-title { margin-top: 8px; font-weight: 600; font-size: 14px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n.card-meta { color: var(--muted); font-size: 12px; margin-top: 2px; }\n\n.row { display: grid; grid-auto-flow: column; grid-auto-columns: 280px; gap: 14px; overflow-x: auto; padding-bottom: 8px; scroll-snap-type: x mandatory; }\n.cont { position: relative; scroll-snap-align: start; border-radius: var(--radius); overflow: hidden; background: var(--bg-2); border: 1px solid var(--line); display: flex; gap: 12px; padding: 10px; }\n.cont img { width: 64px; height: 90px; object-fit: cover; border-radius: 8px; flex: none; }\n.cont .c-title { font-weight: 600; font-size: 14px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n.cont .c-meta { color: var(--muted); font-size: 12px; margin-top: 4px; }\n.progress { height: 4px; background: var(--line); border-radius: 2px; margin-top: 10px; overflow: hidden; }\n.progress i { display: block; height: 100%; background: var(--accent); }\n.cont .x { position: absolute; top: 6px; right: 6px; background: none; border: 0; color: var(--muted); cursor: pointer; font-size: 16px; }\n\n.loader { display: grid; place-items: center; padding: 120px 0; }\n.loader::after { content: \"\"; width: 38px; height: 38px; border: 3px solid var(--line); border-top-color: var(--accent); border-radius: 50%; animation: spin .8s linear infinite; }\n@keyframes spin { to { transform: rotate(360deg); } }\n.error, .empty { text-align: center; padding: 80px 20px; color: var(--muted); }\n.error h2, .empty h2 { color: var(--text); }\n\n/* ---------- home ---------- */\n.spotlight { position: relative; margin: 20px -20px 0; height: min(520px, 62vh); overflow: hidden; border-radius: 0 0 var(--radius) var(--radius); }\n.slide { position: absolute; inset: 0; opacity: 0; transition: opacity .7s; pointer-events: none; }\n.slide.on { opacity: 1; pointer-events: auto; }\n.slide > img { width: 100%; height: 100%; object-fit: cover; }\n.slide::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(90deg, var(--bg) 8%, rgba(13,11,20,.75) 45%, rgba(13,11,20,.1)), linear-gradient(0deg, var(--bg), transparent 40%); }\n.slide-info { position: absolute; z-index: 2; left: 40px; bottom: 56px; max-width: 560px; }\n.slide-info .rank { color: var(--accent); font-weight: 700; }\n.slide-info h1 { margin: 6px 0 10px; font-size: clamp(26px, 4vw, 44px); line-height: 1.1; }\n.slide-info .meta { display: flex; flex-wrap: wrap; gap: 8px; color: var(--muted); font-size: 13px; margin-bottom: 12px; }\n.slide-info .meta span { background: rgba(255,255,255,.08); padding: 2px 8px; border-radius: 6px; }\n.slide-info p { color: #cfcadd; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin: 0 0 18px; }\n.slide-info .actions { display: flex; gap: 10px; }\n.dots { position: absolute; z-index: 3; right: 32px; bottom: 24px; display: flex; gap: 6px; }\n.dots button { width: 8px; height: 8px; border-radius: 4px; border: 0; background: #fff4; cursor: pointer; padding: 0; transition: width .3s; }\n.dots button.on { width: 24px; background: var(--accent); }\n\n.home-grid { display: grid; grid-template-columns: 1fr 320px; gap: 32px; }\n.top10 { display: flex; flex-direction: column; gap: 10px; }\n.top10 a { display: flex; gap: 12px; align-items: center; background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); padding: 8px; }\n.top10 a:hover { border-color: var(--accent-2); }\n.top10 .num { width: 30px; text-align: center; font-size: 22px; font-weight: 800; color: var(--muted); }\n.top10 a:nth-child(-n+3) .num { color: var(--accent); }\n.top10 img { width: 46px; height: 64px; object-fit: cover; border-radius: 6px; }\n.top10 .t { font-weight: 600; font-size: 14px; line-height: 1.3; }\n.top10 .m { color: var(--muted); font-size: 12px; }\n\n/* ---------- anime page ---------- */\n.hero { position: relative; margin: 0 -20px; min-height: 340px; }\n.hero-bg { position: absolute; inset: 0; background-size: cover; background-position: center; filter: blur(2px) brightness(.45); }\n.hero-bg::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(0deg, var(--bg), transparent 70%); }\n.hero-inner { position: relative; display: flex; gap: 28px; padding: 48px 40px 28px; align-items: flex-end; }\n.hero-inner .cover { width: 200px; flex: none; border-radius: var(--radius); box-shadow: 0 20px 50px #000a; }\n.hero-inner h1 { margin: 0 0 4px; font-size: clamp(24px, 3.4vw, 38px); line-height: 1.15; }\n.hero-inner .alt { color: var(--muted); margin-bottom: 12px; }\n.chips { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0 16px; }\n.chip { background: var(--bg-3); border: 1px solid var(--line); padding: 3px 10px; border-radius: 999px; font-size: 13px; color: #d6d1e4; }\na.chip:hover { border-color: var(--accent); }\n.actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }\n\n.detail-grid { display: grid; grid-template-columns: 1fr 300px; gap: 32px; margin-top: 20px; }\n.desc { white-space: pre-line; color: #d6d1e4; }\n.desc.clamp { display: -webkit-box; -webkit-line-clamp: 5; -webkit-box-orient: vertical; overflow: hidden; }\n.link-btn { background: none; border: 0; color: var(--accent); cursor: pointer; padding: 0; font-weight: 600; }\n.info-box { background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; font-size: 14px; }\n.info-box div { padding: 6px 0; border-bottom: 1px solid var(--line); display: flex; gap: 8px; }\n.info-box div:last-child { border: 0; }\n.info-box b { color: var(--muted); font-weight: 500; min-width: 90px; }\n.chars { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 10px; }\n.char { display: flex; justify-content: space-between; background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; font-size: 13px; }\n.char > div { display: flex; gap: 8px; align-items: center; }\n.char > div:last-child { text-align: right; flex-direction: row-reverse; }\n.char img { width: 48px; height: 64px; object-fit: cover; }\n.char small { color: var(--muted); display: block; }\n.trailer { aspect-ratio: 16/9; width: 100%; border: 0; border-radius: var(--radius); }\n.links { display: flex; flex-wrap: wrap; gap: 8px; }\n\n/* ---------- watch page ---------- */\n.watch-grid { display: grid; grid-template-columns: 1fr 360px; gap: 20px; margin-top: 20px; }\n.crumbs { color: var(--muted); font-size: 13px; margin-top: 16px; }\n.crumbs a:hover { color: var(--text); }\n.player { position: relative; background: #000; border-radius: var(--radius); overflow: hidden; aspect-ratio: 16 / 9; }\n.player video { width: 100%; height: 100%; display: block; background: #000; }\n.pl-btn { position: absolute; right: 16px; bottom: 70px; z-index: 5; background: rgba(15,12,24,.9); border: 1px solid #fff3; padding: 10px 16px; border-radius: 10px; cursor: pointer; font-weight: 700; }\n.pl-btn:hover { border-color: var(--accent); }\n.pl-msg { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; padding: 20px; background: rgba(0,0,0,.75); z-index: 6; }\n.pl-bar { display: flex; flex-wrap: wrap; gap: 10px 18px; align-items: center; padding: 12px 14px; background: var(--bg-2); border: 1px solid var(--line); border-top: 0; border-radius: 0 0 var(--radius) var(--radius); font-size: 14px; }\n.pl-bar label { display: flex; align-items: center; gap: 6px; color: var(--muted); cursor: pointer; }\n.pl-bar select { padding: 4px 8px; }\n.pl-bar .spacer { flex: 1; }\n.player-wrap .player { border-radius: var(--radius) var(--radius) 0 0; }\n\n.servers { margin-top: 14px; background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px; display: grid; grid-template-columns: 220px 1fr; gap: 14px; align-items: center; }\n.servers .now { color: var(--muted); font-size: 14px; }\n.servers .now b { color: var(--text); display: block; font-size: 16px; }\n.srv-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 4px 0; }\n.srv-row .lab { width: 44px; color: var(--muted); font-size: 13px; font-weight: 700; text-transform: uppercase; }\n.srv { padding: 6px 14px; border-radius: 8px; border: 1px solid var(--line); background: var(--bg-3); cursor: pointer; font-size: 13px; font-weight: 600; }\n.srv.on { background: var(--accent); color: #160d1c; border-color: var(--accent); }\n\n.ep-box { background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); display: flex; flex-direction: column; max-height: calc(100vh - var(--nav-h) - 40px); position: sticky; top: calc(var(--nav-h) + 20px); }\n.ep-head { padding: 12px 14px; border-bottom: 1px solid var(--line); display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.ep-head h3 { margin: 0; font-size: 15px; flex: 1; }\n.ep-head .input { width: 90px; padding: 5px 10px; }\n.ep-head select { padding: 5px 8px; }\n.ep-list { overflow-y: auto; padding: 10px; display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }\n.ep-list.wide { grid-template-columns: 1fr; }\n.ep { border: 1px solid var(--line); background: var(--bg-3); border-radius: 8px; padding: 8px 4px; cursor: pointer; font-size: 13px; font-weight: 600; text-align: center; }\n.ep-list.wide .ep { text-align: left; padding: 10px 12px; }\n.ep:hover { border-color: var(--muted); }\n.ep.seen { color: var(--muted); }\n.ep.filler { border-color: #b45309; }\n.ep.on { background: var(--accent); color: #160d1c; border-color: var(--accent); }\n.ep-legend { padding: 8px 14px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; }\n\n/* ---------- search ---------- */\n.filters { display: grid; grid-template-columns: 2fr repeat(6, 1fr); gap: 10px; margin-top: 24px; }\n.filters .input { width: 100%; }\n.pager { display: flex; justify-content: center; align-items: center; gap: 10px; margin-top: 28px; color: var(--muted); }\n\n/* ---------- tabs (watchlist, schedule) ---------- */\n.tabs { display: flex; gap: 6px; overflow-x: auto; margin: 24px 0 18px; padding-bottom: 4px; }\n.tab { padding: 8px 16px; border-radius: 999px; border: 1px solid var(--line); background: var(--bg-2); cursor: pointer; white-space: nowrap; font-weight: 600; font-size: 14px; }\n.tab.on { background: var(--text); color: var(--bg); border-color: var(--text); }\n.tab small { opacity: .7; font-weight: 500; }\n.sched { display: flex; flex-direction: column; gap: 8px; }\n.sched a { display: flex; align-items: center; gap: 14px; background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 14px; }\n.sched a:hover { border-color: var(--accent-2); }\n.sched a.past { opacity: .55; }\n.sched .time { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--accent); width: 56px; }\n.sched img { width: 40px; height: 56px; object-fit: cover; border-radius: 6px; }\n.sched .t { flex: 1; font-weight: 600; }\n.sched .e { color: var(--muted); font-size: 13px; white-space: nowrap; }\n\n.page-title { margin: 28px 0 0; font-size: 26px; }\n\n.footer { border-top: 1px solid var(--line); padding: 22px 0; color: var(--muted); font-size: 13px; }\n.footer .container { display: flex; gap: 16px; align-items: center; flex-wrap: wrap; }\n.footer p { margin: 0; }\n.footer a:not(.logo) { color: var(--accent); }\n\n/* ---------- responsive ---------- */\n@media (max-width: 1100px) {\n  .home-grid, .detail-grid, .watch-grid { grid-template-columns: 1fr; }\n  .ep-box { position: static; max-height: 480px; }\n  .filters { grid-template-columns: repeat(3, 1fr); }\n  .filters .q { grid-column: 1 / -1; }\n}\n@media (max-width: 760px) {\n  .container { padding: 0 12px; }\n  .nav-inner { gap: 12px; padding: 0 12px; }\n  .menu-btn { display: block; }\n  .nav-links { display: none; position: absolute; top: var(--nav-h); left: 0; right: 0; flex-direction: column; background: var(--bg-2); border-bottom: 1px solid var(--line); padding: 8px; }\n  .nav-links.open { display: flex; }\n  .nav-search { width: auto; flex: 1; }\n  .spotlight { margin: 0 -12px; height: 440px; }\n  .slide-info { left: 16px; right: 16px; bottom: 48px; }\n  .dots { right: 16px; bottom: 18px; }\n  .hero { margin: 0 -12px; }\n  .hero-inner { flex-direction: column; align-items: flex-start; padding: 24px 16px 16px; }\n  .hero-inner .cover { width: 130px; }\n  .grid { grid-template-columns: repeat(3, 1fr); gap: 12px 8px; }\n  .card-title { font-size: 13px; }\n  .servers { grid-template-columns: 1fr; }\n  .ep-list { grid-template-columns: repeat(5, 1fr); }\n  .filters { grid-template-columns: repeat(2, 1fr); }\n  .pl-btn { bottom: 56px; right: 10px; padding: 8px 12px; font-size: 13px; }\n  .player-wrap { margin: 0 -12px; }\n  .player-wrap .player { border-radius: 0; }\n  .pl-bar { border-radius: 0; border-left: 0; border-right: 0; }\n}\n\n/* ---------- account ---------- */\n.auth-box { max-width: 460px; margin: 48px auto 0; background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); padding: 24px; }\n.auth-form { display: flex; flex-direction: column; gap: 14px; }\n.auth-form label { display: flex; flex-direction: column; gap: 6px; font-weight: 600; font-size: 14px; }\n.auth-form .btn { justify-content: center; }\n.auth-err { background: #3b1220; border: 1px solid #7f1d3a; color: #fecdd3; padding: 8px 12px; border-radius: 8px; font-size: 14px; }\n.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 18px; }\n.stats div { background: var(--bg-3); border-radius: 10px; padding: 12px; text-align: center; }\n.stats b { display: block; font-size: 20px; }\n.stats span { color: var(--muted); font-size: 12px; }\n.logo span { white-space: pre; }\n.player .embed-frame { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; background: #000; }\n.player .embed-frame[hidden] { display: none; }\n.player video[hidden] { display: none; }\n","/js/api.js":"// Tiny fetch wrapper for /api with in-memory caching per page session\nconst memo = new Map();\n\nexport function api(path, { fresh = false } = {}) {\n  if (!fresh && memo.has(path)) return memo.get(path);\n  const p = fetch('/api' + path, { headers: { Accept: 'application/json' } }).then(async (r) => {\n    const data = await r.json().catch(() => ({ error: 'Bad response from server' }));\n    if (!r.ok) throw new Error(data.error || `Request failed (${r.status})`);\n    return data;\n  });\n  if (!fresh) {\n    memo.set(path, p);\n    p.catch(() => memo.delete(path));\n  }\n  return p;\n}\n","/js/app.js":"import { api } from './api.js';\nimport * as store from './store.js';\nimport { Player } from './player.js';\n\nconst app = document.getElementById('app');\nlet cleanups = [];\nlet navToken = 0;\n\n// ---------- helpers ----------\nconst esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst FORMAT = { TV: 'TV', TV_SHORT: 'TV Short', MOVIE: 'Movie', SPECIAL: 'Special', OVA: 'OVA', ONA: 'ONA', MUSIC: 'Music' };\nconst STATUS = { RELEASING: 'Airing', FINISHED: 'Finished', NOT_YET_RELEASED: 'Upcoming', CANCELLED: 'Cancelled', HIATUS: 'Hiatus' };\nconst SEASON = { WINTER: 'Winter', SPRING: 'Spring', SUMMER: 'Summer', FALL: 'Fall' };\nconst GENRES = ['Action', 'Adventure', 'Comedy', 'Drama', 'Fantasy', 'Horror', 'Mahou Shoujo', 'Mecha', 'Music', 'Mystery',\n  'Psychological', 'Romance', 'Sci-Fi', 'Slice of Life', 'Sports', 'Supernatural', 'Thriller'];\nconst score = (s) => (s ? (s / 10).toFixed(1) : null);\nconst fmtDate = (d) => (d?.year ? new Date(d.year, (d.month || 1) - 1, d.day || 1).toLocaleDateString(undefined, { year: 'numeric', month: 'short', ...(d.day ? { day: 'numeric' } : {}) }) : '?');\nconst fmtCountdown = (sec) => {\n  const d = Math.floor(sec / 86400), h = Math.floor((sec % 86400) / 3600), m = Math.floor((sec % 3600) / 60);\n  return d ? `${d}d ${h}h` : h ? `${h}h ${m}m` : `${m}m`;\n};\nconst loader = () => '<div class=\"loader\"></div>';\nconst onCleanup = (fn) => cleanups.push(fn);\n\nfunction epsLabel(a) {\n  const have = a.availableEpisodes;\n  if (a.status === 'RELEASING' && a.episodes) return `${have}/${a.episodes}`;\n  return have || a.episodes || '?';\n}\n\nfunction card(a) {\n  return `<a class=\"card\" href=\"#/anime/${a.id}\" title=\"${esc(a.title)}\">\n    <div class=\"poster\" style=\"--c:${esc(a.color || '#1e1a2b')}\">\n      <img loading=\"lazy\" src=\"${esc(a.cover)}\" alt=\"\">\n      ${a.score ? `<span class=\"badge score\">★ ${score(a.score)}</span>` : ''}\n      ${a.status === 'RELEASING' ? '<span class=\"badge airing\">Airing</span>' : ''}\n      <span class=\"badge eps\">${FORMAT[a.format] === 'Movie' ? 'Movie' : `${epsLabel(a)} eps`}</span>\n    </div>\n    <div class=\"card-title\">${esc(a.title)}</div>\n    <div class=\"card-meta\">${[FORMAT[a.format], a.year].filter(Boolean).join(' · ')}</div>\n  </a>`;\n}\nconst grid = (list) => (list?.length ? `<div class=\"grid\">${list.map(card).join('')}</div>` : '<div class=\"empty\">Nothing here yet.</div>');\nconst section = (title, body, more = '') => `<section class=\"section\"><div class=\"section-head\"><h2>${title}</h2>${more}</div>${body}</section>`;\n\n// ---------- router ----------\nfunction parseHash() {\n  const raw = location.hash.slice(1) || '/';\n  const [path, qs = ''] = raw.split('?');\n  return { parts: path.split('/').filter(Boolean), query: new URLSearchParams(qs) };\n}\n\nfunction setActiveNav(key) {\n  document.querySelectorAll('[data-nav]').forEach((a) => a.classList.toggle('active', a.dataset.nav === key));\n  document.getElementById('nav-links').classList.remove('open');\n}\n\nasync function route() {\n  cleanups.forEach((fn) => { try { fn(); } catch { /* ignore */ } });\n  cleanups = [];\n  const token = ++navToken;\n  const alive = () => token === navToken;\n  const { parts, query } = parseHash();\n  setActiveNav(parts[0] || 'home');\n  window.scrollTo(0, 0);\n  app.innerHTML = loader();\n\n  try {\n    switch (parts[0]) {\n      case undefined: return await viewHome(alive);\n      case 'search': return await viewSearch(query, alive);\n      case 'anime': return await viewAnime(Number(parts[1]), alive);\n      case 'watch': return await viewWatch(Number(parts[1]), query, alive);\n      case 'watchlist': return viewWatchlist(query);\n      case 'schedule': return await viewSchedule(query, alive);\n      case 'account': return viewAccount(query);\n      default: return viewNotFound();\n    }\n  } catch (err) {\n    if (!alive()) return;\n    app.innerHTML = `<div class=\"error\"><h2>Couldn't load this page</h2><p>${esc(err.message)}</p>\n      <button class=\"btn\" id=\"retry\">Try again</button></div>`;\n    document.getElementById('retry').onclick = route;\n  }\n}\n\n// ---------- home ----------\nasync function viewHome(alive) {\n  const d = await api('/home');\n  if (!alive()) return;\n  const cont = store.continueList().filter(p => p.title);\n  app.innerHTML = (cont.length ? section('Continue watching', '<div class=\"row\">' + cont.map(contCard).join('') + '</div>') : '') +\n    section('Recently added', grid(d.trending), '<a href=\"#/search\">Browse catalog ›</a>');\n  app.querySelectorAll('.cont .x').forEach(b => b.onclick = e => {\n    e.preventDefault(); store.removeProgress(Number(b.dataset.id)); b.closest('.cont').remove();\n  });\n}\n\nfunction spotlight(list) {\n  if (!list?.length) return '';\n  return `<section class=\"spotlight\">\n    ${list.map((a, i) => `\n      <div class=\"slide${i === 0 ? ' on' : ''}\">\n        <img src=\"${esc(a.banner)}\" alt=\"\" ${i ? 'loading=\"lazy\"' : ''}>\n        <div class=\"slide-info\">\n          <div class=\"rank\">#${i + 1} Spotlight</div>\n          <h1>${esc(a.title)}</h1>\n          <div class=\"meta\">\n            ${a.format ? `<span>${FORMAT[a.format]}</span>` : ''}\n            ${a.score ? `<span>★ ${score(a.score)}</span>` : ''}\n            ${a.year ? `<span>${a.year}</span>` : ''}\n            <span>${epsLabel(a)} eps</span>\n            ${a.genres.slice(0, 3).map((g) => `<span>${esc(g)}</span>`).join('')}\n          </div>\n          <p>${esc(a.description)}</p>\n          <div class=\"actions\">\n            <a class=\"btn primary\" href=\"#/watch/${a.id}\">▶ Watch now</a>\n            <a class=\"btn\" href=\"#/anime/${a.id}\">Details ›</a>\n          </div>\n        </div>\n      </div>`).join('')}\n    <div class=\"dots\">${list.map((_, i) => `<button class=\"${i === 0 ? 'on' : ''}\" aria-label=\"Slide ${i + 1}\"></button>`).join('')}</div>\n  </section>`;\n}\n\nfunction contCard(p) {\n  const pct = p.duration ? Math.min(100, (p.time / p.duration) * 100) : 0;\n  return `<a class=\"cont\" href=\"#/watch/${p.animeId}?ep=${p.ep}\">\n    <img src=\"${esc(p.cover)}\" alt=\"\" loading=\"lazy\">\n    <div style=\"min-width:0;flex:1\">\n      <div class=\"c-title\">${esc(p.title)}</div>\n      <div class=\"c-meta\">Episode ${p.ep}</div>\n      <div class=\"progress\"><i style=\"width:${pct.toFixed(1)}%\"></i></div>\n    </div>\n    <button class=\"x\" data-id=\"${p.animeId}\" aria-label=\"Remove\">✕</button>\n  </a>`;\n}\n\nfunction top10(list) {\n  return `<div class=\"top10\">${(list || []).map((a, i) => `\n    <a href=\"#/anime/${a.id}\">\n      <span class=\"num\">${String(i + 1).padStart(2, '0')}</span>\n      <img src=\"${esc(a.cover)}\" alt=\"\" loading=\"lazy\">\n      <div><div class=\"t\">${esc(a.title)}</div><div class=\"m\">${[FORMAT[a.format], a.score ? `★ ${score(a.score)}` : ''].filter(Boolean).join(' · ')}</div></div>\n    </a>`).join('')}</div>`;\n}\n\n// ---------- search / browse ----------\nasync function viewSearch(q, alive) {\n  const opt = (list, val) => list.map(x => '<option value=\"' + esc(x) + '\"' + (x === val ? ' selected' : '') + '>' + esc(x) + '</option>').join('');\n  app.innerHTML = '<h1 class=\"page-title\">' + (q.get('q') ? 'Results for “' + esc(q.get('q')) + '”' : 'Browse anime') + '</h1>' +\n    '<form class=\"filters\" id=\"filters\"><input class=\"input q\" name=\"q\" placeholder=\"Title…\" value=\"' + esc(q.get('q') || '') + '\">' +\n    '<select name=\"genre\"><option value=\"\">Any genre</option>' + opt(GENRES, q.get('genre')) + '</select></form><div id=\"results\">' + loader() + '</div>';\n  const form = document.getElementById('filters');\n  const go = () => { const p = new URLSearchParams(); for (const [k,v] of new FormData(form)) if (String(v).trim()) p.set(k,String(v).trim()); location.hash = '#/search' + (p.toString() ? '?' + p : ''); };\n  form.onsubmit = e => { e.preventDefault(); go(); };\n  form.querySelector('select').onchange = go;\n  const d = await api('/search?' + new URLSearchParams(q));\n  if (!alive()) return;\n  const page = d.pageInfo.currentPage;\n  const p = new URLSearchParams(q); p.set('page', page + 1);\n  document.getElementById('results').innerHTML = '<div class=\"section\">' + (d.results.length ? grid(d.results) : '<div class=\"empty\"><h2>No results on this page</h2><p>Try another title or browse the next page.</p></div>') + '</div>' +\n    '<div class=\"pager\"><a class=\"btn sm\" href=\"#/search?' + p + '\">Next page ›</a><span>Page ' + page + '</span></div>';\n}\n\n// ---------- anime details ----------\nfunction listSelect(a) {\n  const entry = store.getEntry(a.id);\n  return `<select id=\"list-status\" aria-label=\"Watchlist\">\n    <option value=\"\">${entry ? 'Remove from list' : '＋ Add to list'}</option>\n    ${store.LIST_STATUSES.map(([k, l]) => `<option value=\"${k}\"${entry?.status === k ? ' selected' : ''}>${l}</option>`).join('')}\n  </select>`;\n}\nfunction bindListSelect(a) {\n  const sel = document.getElementById('list-status');\n  if (!sel) return;\n  sel.onchange = () => {\n    store.setEntry(a, sel.value || null);\n    sel.outerHTML = listSelect(a);\n    bindListSelect(a);\n  };\n}\n\nasync function viewAnime(id, alive) {\n  if (!id) return viewNotFound();\n  const a = await api(`/anime/${id}`);\n  if (!alive()) return;\n  document.title = `${a.title} · animee space`;\n  const prog = store.getProgress(a.id);\n  const canWatch = a.availableEpisodes > 0;\n\n  app.innerHTML = `\n    <section class=\"hero\">\n      <div class=\"hero-bg\" style=\"background-image:url('${esc(a.banner || a.cover)}')\"></div>\n      <div class=\"hero-inner\">\n        <img class=\"cover\" src=\"${esc(a.cover)}\" alt=\"\">\n        <div>\n          <h1>${esc(a.title)}</h1>\n          <div class=\"alt\">${esc([a.titleRomaji !== a.title ? a.titleRomaji : null, a.titleNative].filter(Boolean).join(' · '))}</div>\n          <div class=\"chips\">\n            ${a.score ? `<span class=\"chip\">★ ${score(a.score)}</span>` : ''}\n            ${a.format ? `<span class=\"chip\">${FORMAT[a.format]}</span>` : ''}\n            <span class=\"chip\">${STATUS[a.status] || a.status}</span>\n            <span class=\"chip\">${epsLabel(a)} eps</span>\n            ${a.duration ? `<span class=\"chip\">${a.duration} min</span>` : ''}\n            ${a.genres.map((g) => `<a class=\"chip\" href=\"#/search?genre=${encodeURIComponent(g)}\">${esc(g)}</a>`).join('')}\n          </div>\n          <div class=\"actions\">\n            ${canWatch\n              ? `<a class=\"btn primary\" href=\"#/watch/${a.id}${prog ? `?ep=${prog.ep}` : ''}\">▶ ${prog ? `Continue EP ${prog.ep}` : 'Watch now'}</a>`\n              : '<span class=\"btn\" aria-disabled=\"true\">Not released yet</span>'}\n            ${listSelect(a)}\n          </div>\n          ${a.nextAiring ? `<p class=\"card-meta\" style=\"margin-top:12px\">Episode ${a.nextAiring.episode} airs in ${fmtCountdown(a.nextAiring.timeUntilAiring)}</p>` : ''}\n        </div>\n      </div>\n    </section>\n\n    <div class=\"detail-grid\">\n      <div>\n        <section class=\"section\" style=\"margin-top:12px\">\n          <div class=\"desc clamp\" id=\"desc\">${esc(a.description || 'No description yet.')}</div>\n          ${(a.description || '').length > 400 ? '<button class=\"link-btn\" id=\"more\">Read more</button>' : ''}\n        </section>\n        ${a.trailer ? section('Trailer', `<iframe class=\"trailer\" src=\"https://www.youtube-nocookie.com/embed/${esc(a.trailer)}\" title=\"Trailer\" allowfullscreen loading=\"lazy\"></iframe>`) : ''}\n        ${a.characters.length ? section('Characters & voice actors', `<div class=\"chars\">${a.characters.map((c) => `\n          <div class=\"char\">\n            <div><img src=\"${esc(c.image)}\" alt=\"\" loading=\"lazy\"><span>${esc(c.name)}<small>${esc(c.role)}</small></span></div>\n            ${c.va ? `<div><img src=\"${esc(c.va.image)}\" alt=\"\" loading=\"lazy\"><span>${esc(c.va.name)}<small>Japanese</small></span></div>` : ''}\n          </div>`).join('')}</div>`) : ''}\n        ${a.relations.length ? section('Related', grid(a.relations)) : ''}\n        ${a.recommendations.length ? section('You might also like', grid(a.recommendations)) : ''}\n      </div>\n      <aside>\n        <section class=\"section\" style=\"margin-top:12px\">\n          <div class=\"info-box\">\n            <div><b>Aired</b><span>${fmtDate(a.startDate)} – ${a.status === 'RELEASING' ? 'now' : fmtDate(a.endDate)}</span></div>\n            ${a.season ? `<div><b>Season</b><span>${SEASON[a.season]} ${a.year || ''}</span></div>` : ''}\n            ${a.studios.length ? `<div><b>Studio</b><span>${esc(a.studios.join(', '))}</span></div>` : ''}\n            ${a.source ? `<div><b>Source</b><span>${esc(a.source.replace(/_/g, ' ').toLowerCase())}</span></div>` : ''}\n            ${a.popularity ? `<div><b>Members</b><span>${a.popularity.toLocaleString()}</span></div>` : ''}\n            ${a.synonyms.length ? `<div><b>Also</b><span>${esc(a.synonyms.slice(0, 3).join(', '))}</span></div>` : ''}\n          </div>\n        </section>\n        ${a.streamingLinks.length ? section('Official streams', `<div class=\"links\">${a.streamingLinks.map((l) => `<a class=\"chip\" href=\"${esc(l.url)}\" target=\"_blank\" rel=\"noopener\">${esc(l.site)} ↗</a>`).join('')}</div>`) : ''}\n      </aside>\n    </div>`;\n\n  bindListSelect(a);\n  const more = document.getElementById('more');\n  if (more) more.onclick = () => {\n    const d = document.getElementById('desc');\n    d.classList.toggle('clamp');\n    more.textContent = d.classList.contains('clamp') ? 'Read more' : 'Show less';\n  };\n}\n\n// ---------- watch ----------\nasync function viewWatch(id, query, alive) {\n  if (!id) return viewNotFound();\n  const [a, epData] = await Promise.all([api(`/anime/${id}`), api(`/anime/${id}/episodes`)]);\n  if (!alive()) return;\n  document.title = `Watch ${a.title} · animee space`;\n  const episodes = epData.episodes;\n\n  if (!episodes.length) {\n    app.innerHTML = `<div class=\"empty\"><h2>No episodes yet</h2><p>${esc(a.title)} hasn't released any episodes.</p>\n      <a class=\"btn\" href=\"#/anime/${a.id}\">Back to details</a></div>`;\n    return;\n  }\n\n  const settings = store.getSettings();\n  const prog = store.getProgress(a.id);\n  const wantEp = Number(query.get('ep')) || prog?.ep || 1;\n  let current = episodes.find((e) => e.number === wantEp) || episodes[0];\n  let servers = [];\n  let server = null; // { id, category }\n  const watched = store.watchedSet(a.id);\n  const wide = episodes.length <= 30 && episodes.some((e) => e.title && !/^Episode \\d+$/.test(e.title));\n  const CHUNK = 100;\n\n  app.innerHTML = `\n    <div class=\"crumbs\"><a href=\"#/\">Home</a> › <a href=\"#/anime/${a.id}\">${esc(a.title)}</a> › <span id=\"crumb-ep\"></span></div>\n    <div class=\"watch-grid\">\n      <div>\n        <div class=\"player-wrap\">\n          <div id=\"player\"></div>\n          <div class=\"pl-bar\">\n            <label><input type=\"checkbox\" id=\"opt-autoplay\" ${settings.autoplay ? 'checked' : ''}> Auto next</label>\n            <label><input type=\"checkbox\" id=\"opt-autoskip\" ${settings.autoskip ? 'checked' : ''}> Auto skip intro</label>\n            <label>Quality <select id=\"opt-quality\"><option value=\"-1\">Auto</option></select></label>\n            <span class=\"spacer\"></span>\n            <button class=\"btn sm\" id=\"prev-ep\">‹ Prev</button>\n            <button class=\"btn sm\" id=\"next-ep\">Next ›</button>\n          </div>\n        </div>\n        <div class=\"servers\">\n          <div class=\"now\">You are watching<b id=\"now-ep\"></b>If one server doesn't work, try another.</div>\n          <div id=\"server-list\"></div>\n        </div>\n        <section class=\"section\">\n          <div style=\"display:flex;gap:18px;align-items:flex-start\">\n            <img src=\"${esc(a.cover)}\" alt=\"\" style=\"width:110px;border-radius:10px\">\n            <div>\n              <h2 style=\"margin:0 0 6px\"><a href=\"#/anime/${a.id}\">${esc(a.title)}</a></h2>\n              <div class=\"chips\" style=\"margin:6px 0 10px\">\n                ${a.score ? `<span class=\"chip\">★ ${score(a.score)}</span>` : ''}\n                ${a.format ? `<span class=\"chip\">${FORMAT[a.format]}</span>` : ''}\n                <span class=\"chip\">${STATUS[a.status] || ''}</span>\n              </div>\n              <div class=\"desc clamp\">${esc(a.description || '')}</div>\n              <div style=\"margin-top:12px\">${listSelect(a)}</div>\n            </div>\n          </div>\n        </section>\n        ${a.recommendations.length ? section('You might also like', grid(a.recommendations.slice(0, 12))) : ''}\n      </div>\n      <aside>\n        <div class=\"ep-box\">\n          <div class=\"ep-head\">\n            <h3>Episodes <small class=\"card-meta\">(${episodes.length})</small></h3>\n            ${episodes.length > CHUNK ? `<select id=\"ep-range\">${Array.from({ length: Math.ceil(episodes.length / CHUNK) }, (_, i) => {\n              const from = i * CHUNK + 1, to = Math.min((i + 1) * CHUNK, episodes.length);\n              return `<option value=\"${i}\">${from}-${to}</option>`;\n            }).join('')}</select>` : ''}\n            <input class=\"input\" id=\"ep-find\" type=\"number\" min=\"1\" max=\"${episodes.length}\" placeholder=\"EP #\">\n          </div>\n          <div class=\"ep-list${wide ? ' wide' : ''}\" id=\"ep-list\"></div>\n          ${episodes.some((e) => e.isFiller) ? '<div class=\"ep-legend\">Orange border = filler episode</div>' : ''}\n        </div>\n      </aside>\n    </div>`;\n\n  bindListSelect(a);\n  const $ = (sel) => document.getElementById(sel);\n  const idx = () => episodes.indexOf(current);\n\n  const player = new Player($('player'), {\n    autoskip: () => store.getSettings().autoskip,\n    hasNext: () => idx() < episodes.length - 1,\n    onNext: () => goTo(episodes[idx() + 1]),\n    onEnded: () => {\n      store.markWatched(a.id, current.number);\n      watched.add(current.number);\n      if (store.getSettings().autoplay && idx() < episodes.length - 1) goTo(episodes[idx() + 1]);\n      else renderEpisodes();\n    },\n    onProgress: ({ time, duration, ep }) => {\n      store.saveProgress({ animeId: a.id, ep, time, duration, title: a.title, cover: a.cover });\n      if (duration && time / duration > 0.85 && !watched.has(ep)) {\n        store.markWatched(a.id, ep);\n        watched.add(ep);\n      }\n    },\n  });\n  player.bindQuality($('opt-quality'));\n  onCleanup(() => player.destroy());\n\n  $('opt-autoplay').onchange = (e) => store.setSetting('autoplay', e.target.checked);\n  $('opt-autoskip').onchange = (e) => store.setSetting('autoskip', e.target.checked);\n  $('prev-ep').onclick = () => idx() > 0 && goTo(episodes[idx() - 1]);\n  $('next-ep').onclick = () => idx() < episodes.length - 1 && goTo(episodes[idx() + 1]);\n\n  let range = Math.floor(idx() / CHUNK);\n  function renderEpisodes() {\n    const slice = episodes.length > CHUNK ? episodes.slice(range * CHUNK, (range + 1) * CHUNK) : episodes;\n    $('ep-list').innerHTML = slice.map((e) => `\n      <button class=\"ep${e === current ? ' on' : ''}${watched.has(e.number) ? ' seen' : ''}${e.isFiller ? ' filler' : ''}\"\n        data-n=\"${e.number}\" title=\"${esc(e.title)}${e.isFiller ? ' (filler)' : ''}\">${wide ? `${e.number}. ${esc(e.title)}` : e.number}</button>`).join('');\n    if ($('ep-range')) $('ep-range').value = String(range);\n    $('ep-list').querySelector('.ep.on')?.scrollIntoView({ block: 'nearest' });\n  }\n  $('ep-list').onclick = (e) => {\n    const b = e.target.closest('.ep');\n    if (b) goTo(episodes.find((x) => x.number === Number(b.dataset.n)));\n  };\n  if ($('ep-range')) $('ep-range').onchange = (e) => { range = Number(e.target.value); renderEpisodes(); };\n  $('ep-find').onkeydown = (e) => {\n    if (e.key !== 'Enter') return;\n    const target = episodes.find((x) => x.number === Number(e.target.value));\n    if (target) goTo(target);\n  };\n\n  function renderServers() {\n    const groups = ['sub', 'dub'].map((cat) => {\n      const list = servers.filter((s) => s.category === cat);\n      if (!list.length) return '';\n      return `<div class=\"srv-row\"><span class=\"lab\">${cat}</span>${list.map((s) => `\n        <button class=\"srv${server && server.id === s.id && server.category === cat ? ' on' : ''}\" data-id=\"${esc(s.id)}\" data-cat=\"${cat}\">${esc(s.name)}</button>`).join('')}</div>`;\n    }).join('');\n    $('server-list').innerHTML = groups || '<span class=\"card-meta\">No servers available.</span>';\n  }\n  $('server-list').onclick = (e) => {\n    const b = e.target.closest('.srv');\n    if (!b) return;\n    server = { id: b.dataset.id, category: b.dataset.cat };\n    store.setSetting('category', server.category);\n    renderServers();\n    playSource(player.getCurrentTime());\n  };\n\n  async function playSource(startAt) {\n    const ep = current;\n    try {\n      const src = await api(`/episode/${encodeURIComponent(ep.id)}/sources?server=${encodeURIComponent(server.id)}&category=${server.category}`, { fresh: true });\n      if (!alive() || ep !== current) return;\n      player.load(src, { startAt, meta: { ep: ep.number } });\n    } catch (err) {\n      if (alive()) player.msg(`Couldn't load the video: ${err.message}`);\n    }\n  }\n\n  async function goTo(ep) {\n    if (!ep) return;\n    current = ep;\n    range = Math.floor(idx() / CHUNK);\n    history.replaceState(null, '', `#/watch/${a.id}?ep=${ep.number}`);\n    $('crumb-ep').textContent = `Episode ${ep.number}`;\n    $('now-ep').textContent = `Episode ${ep.number}${ep.isFiller ? ' (filler)' : ''}`;\n    renderEpisodes();\n    player.reset();\n    $('server-list').innerHTML = '<span class=\"card-meta\">Loading servers…</span>';\n    try {\n      const data = await api(`/episode/${encodeURIComponent(ep.id)}/servers`);\n      if (!alive() || ep !== current) return;\n      servers = data.servers;\n      const pref = store.getSettings().category;\n      const s = servers.find((x) => x.category === pref) || servers[0];\n      server = s ? { id: s.id, category: s.category } : null;\n      renderServers();\n      if (!server) return player.msg('No servers for this episode yet.');\n      const p = store.getProgress(a.id);\n      await playSource(p && p.ep === ep.number ? p.time : 0);\n    } catch (err) {\n      if (alive()) player.msg(`Couldn't load servers: ${err.message}`);\n    }\n  }\n\n  goTo(current);\n}\n\n// ---------- watchlist ----------\nfunction viewWatchlist(query) {\n  document.title = 'Watchlist · animee space';\n  const ids = Object.keys(store.getList()).map(Number);\n  store.ensureMeta(ids).then((changed) => { if (changed && parseHash().parts[0] === 'watchlist') route(); });\n  const list = Object.values(store.getList()).filter((e) => e.title).sort((x, y) => y.updated - x.updated);\n  const tab = query.get('tab') || 'all';\n  const count = (k) => list.filter((e) => e.status === k).length;\n  const shown = tab === 'all' ? list : list.filter((e) => e.status === tab);\n\n  app.innerHTML = `\n    <h1 class=\"page-title\">My watchlist</h1>\n    <div class=\"tabs\">\n      <a class=\"tab${tab === 'all' ? ' on' : ''}\" href=\"#/watchlist\">All <small>${list.length}</small></a>\n      ${store.LIST_STATUSES.map(([k, l]) => `<a class=\"tab${tab === k ? ' on' : ''}\" href=\"#/watchlist?tab=${k}\">${l} <small>${count(k)}</small></a>`).join('')}\n    </div>\n    ${shown.length ? grid(shown.map((e) => ({ ...e, availableEpisodes: e.episodes }))) : `<div class=\"empty\"><h2>Nothing here yet</h2><p>Add anime from any details page.</p><a class=\"btn\" href=\"#/search\">Browse anime</a></div>`}\n    ${!store.currentUser() ? '<p class=\"card-meta\" style=\"text-align:center;margin-top:24px\"><a href=\"#/account\" style=\"color:var(--accent)\">Sign in</a> to sync your list and history across devices.</p>' : ''}`;\n}\n\n// ---------- account ----------\nfunction viewAccount(query) {\n  document.title = 'Account · animee space';\n  const user = store.currentUser();\n\n  if (user) {\n    const list = Object.values(store.getList());\n    const history = store.continueList().length;\n    const last = store.sync.lastSync ? new Date(store.sync.lastSync).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' }) : 'not yet';\n    app.innerHTML = `\n      <div class=\"auth-box\">\n        <h1 class=\"page-title\" style=\"margin-top:0\">Hey, ${esc(user.name)} 👋</h1>\n        <p class=\"card-meta\">Your watchlist, watch history and player settings sync to this account.</p>\n        <div class=\"stats\">\n          <div><b>${list.length}</b><span>in watchlist</span></div>\n          <div><b>${history}</b><span>in progress</span></div>\n          <div><b id=\"last-sync\">${last}</b><span>last synced</span></div>\n        </div>\n        <div class=\"actions\" style=\"margin-top:18px\">\n          <button class=\"btn primary\" id=\"sync-now\">Sync now</button>\n          <button class=\"btn\" id=\"logout\">Sign out</button>\n          <button class=\"btn\" id=\"logout-all\">Sign out everywhere</button>\n        </div>\n        <label class=\"card-meta\" style=\"display:flex;gap:8px;margin-top:14px;cursor:pointer\">\n          <input type=\"checkbox\" id=\"clear-local\"> Also clear the list and history saved in this browser when signing out\n        </label>\n      </div>`;\n    document.getElementById('sync-now').onclick = async (e) => {\n      e.target.disabled = true;\n      await store.sync.pull().catch(() => {});\n      route();\n    };\n    const out = (everywhere) => async () => {\n      await store.logout({ everywhere, clearLocal: document.getElementById('clear-local').checked });\n      location.hash = '#/';\n    };\n    document.getElementById('logout').onclick = out(false);\n    document.getElementById('logout-all').onclick = out(true);\n    return;\n  }\n\n  const mode = query.get('mode') === 'register' ? 'register' : 'login';\n  app.innerHTML = `\n    <div class=\"auth-box\">\n      <div class=\"tabs\" style=\"margin-top:0\">\n        <a class=\"tab${mode === 'login' ? ' on' : ''}\" href=\"#/account\">Sign in</a>\n        <a class=\"tab${mode === 'register' ? ' on' : ''}\" href=\"#/account?mode=register\">Create account</a>\n      </div>\n      <form id=\"auth-form\" class=\"auth-form\">\n        <label>Username<input class=\"input\" name=\"username\" autocomplete=\"username\" required minlength=\"3\" maxlength=\"20\" pattern=\"[A-Za-z0-9_]+\"></label>\n        <label>Password<input class=\"input\" name=\"password\" type=\"password\" autocomplete=\"${mode === 'login' ? 'current-password' : 'new-password'}\" required minlength=\"8\" maxlength=\"128\"></label>\n        <div class=\"auth-err\" id=\"auth-err\" hidden></div>\n        <button class=\"btn primary\" type=\"submit\">${mode === 'login' ? 'Sign in' : 'Create account'}</button>\n        <p class=\"card-meta\">${mode === 'login' ? 'No account yet? <a href=\"#/account?mode=register\" style=\"color:var(--accent)\">Create one</a>' : 'No email needed. Anything you already watched in this browser gets added to your account.'}</p>\n      </form>\n    </div>`;\n\n  const form = document.getElementById('auth-form');\n  form.onsubmit = async (e) => {\n    e.preventDefault();\n    const btn = form.querySelector('button');\n    const err = document.getElementById('auth-err');\n    btn.disabled = true;\n    err.hidden = true;\n    try {\n      const { username, password } = Object.fromEntries(new FormData(form));\n      await (mode === 'login' ? store.login(username, password) : store.register(username, password));\n      location.hash = '#/';\n    } catch (ex) {\n      err.textContent = ex.message;\n      err.hidden = false;\n      btn.disabled = false;\n    }\n  };\n}\n\n// ---------- schedule ----------\nasync function viewSchedule() {\n  app.innerHTML = '<div class=\"empty\"><h2>Schedule unavailable</h2><p>The Anikoto API currently documents recent anime and series/episode data, but no airing-schedule endpoint.</p><a class=\"btn\" href=\"#/\">Back home</a></div>';\n}\n\nfunction viewNotFound() {\n  app.innerHTML = '<div class=\"empty\"><h2>404</h2><p>This page doesn\\'t exist.</p><a class=\"btn\" href=\"#/\">Go home</a></div>';\n}\n\n// ---------- nav search with suggestions ----------\nfunction setupSearch() {\n  const form = document.getElementById('nav-search');\n  const input = form.querySelector('input');\n  const box = document.getElementById('suggest');\n  let timer = null;\n  let seq = 0;\n\n  form.onsubmit = (e) => {\n    e.preventDefault();\n    const q = input.value.trim();\n    box.hidden = true;\n    input.blur();\n    if (q) location.hash = '#/search?q=' + encodeURIComponent(q);\n  };\n  input.oninput = () => {\n    clearTimeout(timer);\n    const q = input.value.trim();\n    if (q.length < 2) { box.hidden = true; return; }\n    timer = setTimeout(async () => {\n      const my = ++seq;\n      try {\n        const d = await api('/search?q=' + encodeURIComponent(q));\n        if (my !== seq) return;\n        box.innerHTML = d.results.slice(0, 5).map((a) => `\n          <a href=\"#/anime/${a.id}\"><img src=\"${esc(a.cover)}\" alt=\"\">\n            <div><div class=\"s-title\">${esc(a.title)}</div><div class=\"s-meta\">${[FORMAT[a.format], a.year, STATUS[a.status]].filter(Boolean).join(' · ')}</div></div></a>`).join('') +\n          `<a class=\"s-all\" href=\"#/search?q=${encodeURIComponent(q)}\">View all results ›</a>`;\n        box.hidden = false;\n      } catch { box.hidden = true; }\n    }, 300);\n  };\n  box.onclick = () => { box.hidden = true; input.value = ''; };\n  document.addEventListener('click', (e) => { if (!form.contains(e.target)) box.hidden = true; });\n}\n\n// ---------- boot ----------\ndocument.getElementById('menu-btn').onclick = () => document.getElementById('nav-links').classList.toggle('open');\nsetupSearch();\nwindow.addEventListener('hashchange', () => { document.title = 'animee space'; route(); });\n\n// account label in the nav + refresh list pages after the first sync\nconst navAccount = document.getElementById('nav-account');\nlet firstSync = true;\nstore.onSyncChange(({ user, synced }) => {\n  navAccount.textContent = user ? user.name : 'Sign in';\n  if (synced && firstSync) {\n    firstSync = false;\n    const page = parseHash().parts[0];\n    if (page === undefined || page === 'watchlist') route(); // never interrupt the player\n  }\n});\n\nroute();\nstore.initAccount();\n","/js/player.js":"// Video player: MegaPlay iframe embeds with validated postMessage tracking,\n// plus HLS support for any future first-party source.\n\nexport class Player {\n  /**\n   * @param {HTMLElement} root\n   * @param {{onProgress?:Function,onEnded?:Function,onNext?:Function,hasNext?:Function,autoskip?:Function}} opts\n   */\n  constructor(root, opts = {}) {\n    this.root = root;\n    this.opts = opts;\n    this.hls = null;\n    this.data = null;\n    this.lastSave = 0;\n    this.retries = 0;\n    this.embedTime = 0;\n    this.embedLastSave = 0;\n    this.embedOrigin = null;\n\n    root.innerHTML = `\n      <div class=\"player\">\n        <video playsinline controls preload=\"metadata\"></video>\n        <iframe class=\"embed-frame\" title=\"Anime episode player\" allow=\"autoplay; fullscreen; picture-in-picture; encrypted-media\" allowfullscreen referrerpolicy=\"strict-origin-when-cross-origin\" hidden></iframe>\n        <button class=\"pl-btn skip\" type=\"button\" hidden>Skip intro ⏭</button>\n        <button class=\"pl-btn next\" type=\"button\" hidden>Next episode ▶</button>\n        <div class=\"pl-msg\" hidden></div>\n      </div>`;\n    this.video = root.querySelector('video');\n    this.iframe = root.querySelector('iframe');\n    this.skipBtn = root.querySelector('.skip');\n    this.nextBtn = root.querySelector('.next');\n    this.msgEl = root.querySelector('.pl-msg');\n    this.quality = null; // <select> set via bindQuality()\n\n    this.skipBtn.onclick = () => this.skipIntro();\n    this.nextBtn.onclick = () => this.opts.onNext?.();\n\n    this.onTime = () => this.tick();\n    this.onMessage = (event) => this.handleEmbedMessage(event);\n    window.addEventListener('message', this.onMessage);\n    this.onEnd = () => {\n      this.save(true);\n      this.opts.onEnded?.();\n    };\n    this.video.addEventListener('timeupdate', this.onTime);\n    this.video.addEventListener('ended', this.onEnd);\n    this.video.addEventListener('pause', () => this.save(true));\n  }\n\n  bindQuality(select) {\n    this.quality = select;\n    select.onchange = () => {\n      if (this.hls) this.hls.currentLevel = Number(select.value);\n    };\n  }\n\n  msg(text) {\n    this.msgEl.textContent = text;\n    this.msgEl.hidden = !text;\n  }\n\n  reset() {\n    this.save(true);\n    if (this.hls) { this.hls.destroy(); this.hls = null; }\n    const v = this.video;\n    v.pause();\n    v.querySelectorAll('track').forEach((t) => t.remove());\n    v.removeAttribute('src');\n    v.load();\n    this.skipBtn.hidden = true;\n    this.nextBtn.hidden = true;\n    this.retries = 0;\n    this.msg('');\n    this.iframe.hidden = true;\n    this.iframe.removeAttribute('src');\n    this.video.hidden = false;\n    this.embedTime = 0;\n    this.embedLastSave = 0;\n    this.embedOrigin = null;\n    if (this.quality) { this.quality.disabled = false; this.quality.innerHTML = '<option value=\"-1\">Auto</option>'; }\n  }\n\n  /** @param {{sources:Array,tracks?:Array,intro?:object,outro?:object}} data */\n  load(data, { startAt = 0, meta = {} } = {}) {\n    this.reset();\n    this.data = data;\n    this.meta = meta;\n    if (data.embedUrl) {\n      this.video.hidden = true;\n      this.iframe.hidden = false;\n      this.embedOrigin = 'https://megaplay.buzz';\n      this.iframe.src = data.embedUrl;\n      if (this.quality) this.quality.disabled = true;\n      this.msg('');\n      return;\n    }\n    const v = this.video;\n    const src = (data.sources || [])[0];\n    if (!src) return this.msg('No video source for this episode.');\n\n    for (const t of data.tracks || []) {\n      const el = document.createElement('track');\n      el.kind = 'subtitles';\n      el.label = t.label || t.lang;\n      el.srclang = t.lang || 'und';\n      el.src = t.url;\n      if (t.default) el.default = true;\n      v.appendChild(el);\n    }\n\n    const start = () => {\n      if (startAt > 5 && (!v.duration || startAt < v.duration - 15)) v.currentTime = startAt;\n      v.play().catch(() => { /* autoplay blocked; user presses play */ });\n    };\n\n    const Hls = window.Hls;\n    if (src.type === 'hls' && Hls && Hls.isSupported()) {\n      const hls = new Hls({ capLevelToPlayerSize: true, maxBufferLength: 30 });\n      this.hls = hls;\n      hls.loadSource(src.url);\n      hls.attachMedia(v);\n      hls.on(Hls.Events.MANIFEST_PARSED, () => {\n        this.fillQualities();\n        start();\n      });\n      hls.on(Hls.Events.ERROR, (_e, d) => {\n        if (!d.fatal) return;\n        if (this.retries++ >= 3) {\n          this.msg('This stream failed to load. Try another server.');\n          hls.destroy();\n          this.hls = null;\n          return;\n        }\n        if (d.type === Hls.ErrorTypes.NETWORK_ERROR) hls.startLoad();\n        else if (d.type === Hls.ErrorTypes.MEDIA_ERROR) hls.recoverMediaError();\n        else this.msg('Playback error. Try another server.');\n      });\n    } else if (src.type !== 'hls' || v.canPlayType('application/vnd.apple.mpegurl')) {\n      v.src = src.url;\n      v.addEventListener('loadedmetadata', start, { once: true });\n      v.addEventListener('error', () => this.msg('This stream failed to load. Try another server.'), { once: true });\n    } else {\n      this.msg('Your browser can’t play this stream.');\n    }\n  }\n\n  handleEmbedMessage(event) {\n    if (!this.embedOrigin || event.origin !== this.embedOrigin || event.source !== this.iframe.contentWindow) return;\n    let data = event.data;\n    if (typeof data === 'string') {\n      try { data = JSON.parse(data); } catch { return; }\n    }\n    if (!data || typeof data !== 'object') return;\n    if (data.channel && data.channel !== 'megacloud') return;\n    if (data.event === 'time' && Number.isFinite(Number(data.time))) {\n      this.embedTime = Math.max(0, Number(data.time));\n      const duration = Number(data.duration) || 0;\n      this.saveEmbed(false, duration);\n    }\n    if (data.type === 'watching-log' && Number.isFinite(Number(data.currentTime))) {\n      this.embedTime = Math.max(0, Number(data.currentTime));\n      this.saveEmbed(false, Number(data.duration) || 0);\n    }\n    if (data.event === 'complete') {\n      this.embedTime = Number(data.duration) || this.embedTime;\n      this.saveEmbed(true, Number(data.duration) || 0);\n      this.nextBtn.hidden = !this.opts.hasNext?.();\n      this.opts.onEnded?.();\n    }\n    if (data.event === 'error') this.msg('The embedded player reported a playback error. Try another language/server.');\n  }\n\n  saveEmbed(force, duration = 0) {\n    const now = Date.now();\n    if (!force && now - this.embedLastSave < 5000) return;\n    this.embedLastSave = now;\n    this.opts.onProgress?.({ time: this.embedTime, duration, ...this.meta });\n  }\n\n  getCurrentTime() { return this.iframe.hidden ? (this.video.currentTime || 0) : this.embedTime; }\n\n  fillQualities() {\n    if (!this.quality || !this.hls) return;\n    const levels = this.hls.levels\n      .map((l, i) => ({ i, h: l.height }))\n      .filter((l) => l.h)\n      .sort((a, b) => b.h - a.h);\n    this.quality.innerHTML = '<option value=\"-1\">Auto</option>' +\n      levels.map((l) => `<option value=\"${l.i}\">${l.h}p</option>`).join('');\n  }\n\n  inIntro(t) {\n    const intro = this.data?.intro;\n    return intro && t >= intro.start && t < intro.end - 1;\n  }\n\n  skipIntro() {\n    if (this.data?.intro) this.video.currentTime = this.data.intro.end;\n  }\n\n  tick() {\n    const v = this.video;\n    const t = v.currentTime;\n    const intro = this.inIntro(t);\n    if (intro && this.opts.autoskip?.()) this.skipIntro();\n    this.skipBtn.hidden = !intro;\n\n    const outro = this.data?.outro;\n    const nearEnd = v.duration && (outro ? t >= outro.start : v.duration - t < 25);\n    this.nextBtn.hidden = !(nearEnd && this.opts.hasNext?.());\n\n    this.save(false);\n  }\n\n  save(force) {\n    const v = this.video;\n    if (!this.data || !v || !v.duration || !Number.isFinite(v.duration)) return;\n    const now = Date.now();\n    if (!force && now - this.lastSave < 5000) return;\n    this.lastSave = now;\n    this.opts.onProgress?.({ time: v.currentTime, duration: v.duration, ...this.meta });\n  }\n\n  destroy() {\n    this.reset();\n    this.video.removeEventListener('timeupdate', this.onTime);\n    this.video.removeEventListener('ended', this.onEnd);\n    window.removeEventListener('message', this.onMessage);\n    this.data = null;\n  }\n}\n","/js/store.js":"// Library (watchlist + progress + watched episodes) and settings.\n// Always saved in this browser; when signed in, changes also sync to your account.\n//\n// One entry per anime: { a, s, ep, t, d, w, u, m }\n//   s  list status (0 none, 1 watching, 2 planning, 3 completed, 4 on hold, 5 dropped)\n//   ep last episode opened, t/d seconds watched / episode length\n//   w  watched episode numbers (array here, compact bitset on the server)\n//   u  last change (unix seconds)\n//   m  cached title/cover for display — local only, never uploaded\n\nimport { api } from './api.js';\n\nconst PREFIX = 'animee-space:';\nconst read = (key, fallback) => {\n  try { const raw = localStorage.getItem(PREFIX + key); return raw ? JSON.parse(raw) : fallback; } catch { return fallback; }\n};\nconst write = (key, value) => {\n  try { localStorage.setItem(PREFIX + key, JSON.stringify(value)); } catch { /* full or blocked */ }\n};\nconst now = () => Math.floor(Date.now() / 1000);\n\nexport const LIST_STATUSES = [\n  ['watching', 'Watching'],\n  ['planning', 'Plan to watch'],\n  ['completed', 'Completed'],\n  ['paused', 'On hold'],\n  ['dropped', 'Dropped'],\n];\nconst CODE = { watching: 1, planning: 2, completed: 3, paused: 4, dropped: 5 };\nconst NAME = Object.fromEntries(Object.entries(CODE).map(([k, v]) => [v, k]));\n\nlet lib = read('lib', {});\nlet dirty = new Set(read('dirty', []));\nconst saveLib = () => { write('lib', lib); write('dirty', [...dirty]); };\n\nconst metaOf = (a) => ({ title: a.title, cover: a.cover, format: a.format, episodes: a.episodes ?? null, year: a.year ?? null, score: a.score ?? null });\nfunction entry(id) {\n  return lib[id] || (lib[id] = { a: Number(id), s: 0, ep: 0, t: 0, d: 0, w: [], u: 0, m: null });\n}\nfunction touch(e) {\n  e.u = now();\n  if (!e.s && !e.ep && !e.w.length) delete lib[e.a];\n  dirty.add(e.a);\n  saveLib();\n  sync.schedule();\n}\n\n// ---------- watchlist ----------\nexport function getList() {\n  const out = {};\n  for (const e of Object.values(lib)) {\n    if (e.s) out[e.a] = { id: e.a, ...(e.m || {}), status: NAME[e.s], updated: e.u };\n  }\n  return out;\n}\nexport const getEntry = (id) => (lib[id]?.s ? { status: NAME[lib[id].s] } : null);\nexport function setEntry(anime, status) {\n  const e = entry(anime.id);\n  e.s = CODE[status] || 0;\n  e.m = metaOf(anime);\n  touch(e);\n}\n\n// ---------- progress ----------\nexport function getProgress(id) {\n  const e = lib[id];\n  return e?.ep ? { animeId: e.a, ep: e.ep, time: e.t, duration: e.d, title: e.m?.title, cover: e.m?.cover } : null;\n}\nexport function saveProgress({ animeId, ep, time, duration, title, cover }) {\n  const e = entry(animeId);\n  e.ep = ep;\n  e.t = Math.round(time || 0);\n  e.d = Math.round(duration || 0);\n  if (title) e.m = { ...(e.m || {}), title, cover };\n  touch(e);\n}\nexport function removeProgress(id) {\n  const e = lib[id];\n  if (!e) return;\n  e.ep = 0; e.t = 0; e.d = 0;\n  touch(e);\n}\nexport const continueList = () => Object.values(lib)\n  .filter((e) => e.ep)\n  .sort((x, y) => y.u - x.u)\n  .slice(0, 12)\n  .map((e) => ({ animeId: e.a, ep: e.ep, time: e.t, duration: e.d, title: e.m?.title, cover: e.m?.cover, updated: e.u }));\n\n// ---------- watched ----------\nexport const watchedSet = (id) => new Set(lib[id]?.w || []);\nexport function markWatched(id, number) {\n  const e = entry(id);\n  if (e.w.includes(number)) return;\n  e.w.push(number);\n  touch(e);\n}\n\n// ---------- missing titles/posters (e.g. history synced from another device) ----------\nconst metaTried = new Set(); // ask AniList once per id per page load, even if it has no result\nexport async function ensureMeta(ids) {\n  const missing = ids.filter((id) => lib[id] && !lib[id].m?.title && !metaTried.has(id)).slice(0, 10);\n  if (!missing.length) return false;\n  missing.forEach((id) => metaTried.add(id));\n  try {\n    const { results } = await api('/batch?ids=' + missing.join(','));\n    let filled = false;\n    for (const a of results) if (lib[a.id]) { lib[a.id].m = metaOf(a); filled = true; }\n    if (filled) write('lib', lib);\n    return filled;\n  } catch { return false; }\n}\nexport const libraryIds = () => Object.keys(lib).map(Number);\n\n// ---------- settings ----------\nlet settings = { autoplay: true, autoskip: false, category: 'sub', ...read('settings', {}) };\nexport const getSettings = () => ({ ...settings });\nexport function setSetting(key, value) {\n  settings = { ...settings, [key]: value };\n  write('settings', settings);\n  write('settingsDirty', true);\n  sync.schedule();\n}\nconst prefsBits = () => (settings.autoplay ? 1 : 0) | (settings.autoskip ? 2 : 0) | (settings.category === 'dub' ? 4 : 0);\nfunction applyPrefs(bits) {\n  settings = { ...settings, autoplay: !!(bits & 1), autoskip: !!(bits & 2), category: bits & 4 ? 'dub' : 'sub' };\n  write('settings', settings);\n}\n\n// ---------- bitsets ----------\nfunction toBits(nums) {\n  if (!nums?.length) return null;\n  const bytes = new Uint8Array(Math.ceil(Math.max(...nums) / 8));\n  for (const n of nums) if (n > 0) bytes[(n - 1) >> 3] |= 1 << ((n - 1) & 7);\n  let s = '';\n  for (const b of bytes) s += String.fromCharCode(b);\n  return btoa(s);\n}\nfunction fromBits(b64) {\n  if (!b64) return [];\n  const out = [];\n  const bin = atob(b64);\n  for (let i = 0; i < bin.length; i++) {\n    const byte = bin.charCodeAt(i);\n    for (let bit = 0; bit < 8; bit++) if (byte & (1 << bit)) out.push(i * 8 + bit + 1);\n  }\n  return out;\n}\nconst toRow = (e) => ({ a: e.a, s: e.s, ep: e.ep, t: e.t, d: e.d, w: toBits(e.w), u: e.u });\n\n// ---------- sync ----------\nconst listeners = new Set();\nexport const onSyncChange = (fn) => { listeners.add(fn); return () => listeners.delete(fn); };\nconst emit = (state) => listeners.forEach((fn) => { try { fn(state); } catch { /* ignore */ } });\n\n// Take a row from the server, unless this browser has a newer change. Watched episodes are always combined.\nfunction adopt(row) {\n  const local = lib[row.a];\n  const w = [...new Set([...(local?.w || []), ...fromBits(row.w)])];\n  if (local && local.u > row.u) { local.w = w; return; }\n  if (row.deleted) { delete lib[row.a]; return; }\n  lib[row.a] = { a: row.a, s: row.s, ep: row.ep, t: row.t, d: row.d, w, u: row.u, m: local?.m || null };\n}\n\nasync function post(path, body, { keepalive = false } = {}) {\n  const r = await fetch('/api' + path, {\n    method: 'POST', credentials: 'same-origin', keepalive,\n    headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}),\n  });\n  const data = await r.json().catch(() => ({}));\n  if (!r.ok) throw Object.assign(new Error(data.error || `Request failed (${r.status})`), { status: r.status });\n  return data;\n}\n\nexport const sync = {\n  user: null,\n  timer: null,\n  busy: false,\n  lastSync: null,\n\n  schedule(delay = 20000) {\n    if (!this.user || this.timer) return;\n    this.timer = setTimeout(() => { this.timer = null; this.push(); }, delay);\n  },\n\n  async push({ keepalive = false } = {}) {\n    if (!this.user || this.busy) return;\n    const ids = [...dirty].slice(0, 200);\n    const sendPrefs = read('settingsDirty', false);\n    if (!ids.length && !sendPrefs) return;\n    this.busy = true;\n    try {\n      const rows = ids.map((id) => (lib[id] ? toRow(lib[id]) : { a: id, s: 0, ep: 0, t: 0, d: 0, w: null, u: now() }));\n      const sentU = new Map(rows.map((r) => [r.a, lib[r.a]?.u]));\n      const res = await post('/me/sync', { rows, ...(sendPrefs ? { prefs: prefsBits() } : {}) }, { keepalive });\n      // only clear what didn't change again while the request was in flight\n      ids.forEach((id) => { if (lib[id]?.u === sentU.get(id)) dirty.delete(id); });\n      res.rows.forEach(adopt);\n      if (sendPrefs) write('settingsDirty', false);\n      saveLib();\n      this.lastSync = Date.now();\n      emit({ user: this.user, synced: true });\n      if (dirty.size) this.schedule(2000);\n    } catch (err) {\n      if (err.status === 401) this.signedOut();\n      else this.schedule(60000); // offline or server busy: try again later\n    } finally {\n      this.busy = false;\n    }\n  },\n\n  // full download + merge, used on sign-in and page load\n  async pull() {\n    const res = await fetch('/api/me/library', { credentials: 'same-origin' });\n    if (res.status === 401) return this.signedOut();\n    if (!res.ok) return;\n    const data = await res.json();\n    const server = new Map(data.rows.map((r) => [r.a, r]));\n    for (const row of data.rows) {\n      const local = lib[row.a];\n      if (local) {\n        const serverWatched = new Set(fromBits(row.w));\n        if (local.u > row.u || local.w.some((n) => !serverWatched.has(n))) dirty.add(row.a);\n      }\n      adopt(row);\n    }\n    // anything only this browser has gets uploaded\n    for (const id of Object.keys(lib)) if (!server.has(Number(id))) dirty.add(Number(id));\n    if (!read('settingsDirty', false)) applyPrefs(data.prefs);\n    saveLib();\n    this.lastSync = Date.now();\n    emit({ user: this.user, synced: true });\n    await this.push();\n  },\n\n  signedOut() {\n    this.user = null;\n    clearTimeout(this.timer);\n    this.timer = null;\n    emit({ user: null });\n  },\n};\n\n// ---------- account ----------\nexport async function initAccount() {\n  try {\n    const r = await fetch('/api/auth/me', { credentials: 'same-origin' });\n    const d = await r.json();\n    sync.user = d.user || null;\n  } catch { sync.user = null; }\n  emit({ user: sync.user });\n  if (sync.user) await sync.pull().catch(() => {});\n  return sync.user;\n}\nexport async function register(username, password) {\n  const d = await post('/auth/register', { username, password });\n  sync.user = d.user;\n  await sync.pull();\n  return d.user;\n}\nexport async function login(username, password) {\n  const d = await post('/auth/login', { username, password });\n  sync.user = d.user;\n  await sync.pull();\n  return d.user;\n}\nexport async function logout({ everywhere = false, clearLocal = false } = {}) {\n  await sync.push().catch(() => {});\n  await post(everywhere ? '/auth/logout-all' : '/auth/logout').catch(() => {});\n  if (clearLocal) { lib = {}; dirty = new Set(); saveLib(); }\n  sync.signedOut();\n}\nexport const currentUser = () => sync.user;\n\n// upload before the tab closes or goes to the background\ndocument.addEventListener('visibilitychange', () => {\n  if (document.visibilityState === 'hidden' && sync.user && dirty.size) {\n    clearTimeout(sync.timer);\n    sync.timer = null;\n    sync.push({ keepalive: true });\n  }\n});\n","/favicon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><defs><linearGradient id=\"g\" x1=\"0\" x2=\"1\" y1=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ff7eb6\"/><stop offset=\"1\" stop-color=\"#a78bfa\"/></linearGradient></defs><rect width=\"64\" height=\"64\" rx=\"16\" fill=\"#0d0b14\"/><path d=\"M24 18 L48 32 L24 46 Z\" fill=\"url(#g)\"/></svg>\n","/robots.txt":"User-agent: *\nDisallow: /\n"};
